  assert.doesNotMatch(h.html,/const\s+STARTER\s*=/);assert.doesNotMatch(h.html,/const\s+SCOUT_STARTER\s*=/);
});
test('Current Tech Docs render through one owner without accumulating historical sections',()=>{
